// --- WASM acceleration (libs/web_bridge) ---
// Loaded asynchronously so the bridge is never blocked on it: every helper below checks RD
// and falls back to the JS implementation while it is still null. Both sides implement the
// same primitives (XSalsa20-Poly1305, X25519, Ed25519, zstd), so a session that starts on
// the JS path keeps working after the module arrives.
let RD = null;

const wasmReady = (async () => {
  try {
    const m = await import('./pkg/web_bridge.js');
    await m.default();
    // Probe one export from each group, so a stale or partial build is not half-trusted.
    if (typeof m.secretboxSeal === 'function' && typeof m.parseFields === 'function'
        && typeof m.zstdDecompress === 'function' && typeof m.sha256 === 'function'
        && typeof m.pbUint32 === 'function' && typeof m.crc32Update === 'function'
        && typeof m.splitMessages === 'function' && typeof m.toBase64 === 'function'
        && typeof m.bytesToHex === 'function' && typeof m.hashPassword === 'function'
        && typeof m.secretboxSealSeq === 'function' && typeof m.zipCreate === 'function'
        && typeof m.encodeFileBlock === 'function') {
      RD = m;
      console.log('[WebBridge] wasm bridge ready, version', m.version());
    } else {
      console.warn('[WebBridge] wasm bridge is missing exports, using JS fallback');
    }
  } catch(e) {
    console.warn('[WebBridge] wasm bridge unavailable, using JS fallback:', e);
  }
})();

// zstd runs on the wasm module; fzstd (window.fzstd, vendored like tweetnacl) is the pure-JS
// fallback for a tab where wasm never loaded, which otherwise left compressed terminal data and
// file blocks undecodable. Both take and return a Uint8Array; the wasm side returns null on a bad
// frame, and fzstd throws, so the throw is caught and normalised to null to keep callers uniform.
function zstdDecompress(data) {
  if (RD) return RD.zstdDecompress(data);
  if (window.fzstd && typeof window.fzstd.decompress === 'function') {
    try {
      return window.fzstd.decompress(data);
    } catch(e) {
      console.warn('[WebBridge] fzstd decompression failed:', e);
      return null;
    }
  }
  return null;
}

// --- SHA-256 ---
